// Project: Agrisense Node.js Production Backend
// Files included below (copy each to its own file):
// 1) server.js        - main Express server
// 2) worker.js        - background worker (Bull) that processes NDVI jobs
// 3) package.json     - npm dependencies & scripts
// 4) README.md        - setup & run instructions

/* ==================================================
   File: server.js
   ================================================== */

/*
  Express server that exposes:
   - POST /api/get-layer    -> returns Earth Engine tile URL for a polygon + layer
   - POST /api/get-stats    -> enqueues NDVI time-series job (returns job id)
   - GET  /api/job/:id      -> job status/result

  Production-ready features:
   - Service account authentication using Earth Engine npm package
   - Background queue using Bull (Redis)
   - Input validation
   - Basic caching (in Redis) for map tiles
   - Logging and structured errors

  Environment variables (recommended):
   - EE_KEY_FILE          Path to service account JSON key (or set EE_PRIVATE_KEY and EE_CLIENT_EMAIL)
   - REDIS_URL            Redis connection string (default: redis://127.0.0.1:6379)
   - PORT                 Server port (default 3000)
   - GEE_PROJECT          Optional GCP project (used if needed)
*/

const express = require('express');
const bodyParser = require('body-parser');
const cors = require('cors');
const ee = require('@google/earthengine');
const fs = require('fs');
const path = require('path');
const util = require('util');
const Queue = require('bull');
const IORedis = require('ioredis');

// Config
const PORT = process.env.PORT || 3000;
const REDIS_URL = process.env.REDIS_URL || 'redis://127.0.0.1:6379';
const EE_KEY_FILE = process.env.EE_KEY_FILE || './service-account-key.json';
const CACHE_TTL = 60; // seconds

// Init Redis and Bull queues
const redis = new IORedis(REDIS_URL);
const ndviQueue = new Queue('ndvi-jobs', {
  redis: REDIS_URL,
});

// Simple helper to promisify ee calls that use callbacks
function eeInitializeWithPrivateKey(keyObj) {
  return new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(keyObj, () => {
      // After authenticating, initialize
      ee.initialize(null, null, () => {
        resolve();
      }, (err) => reject(new Error('ee.initialize error: ' + err)));
    }, (err) => reject(new Error('authenticateViaPrivateKey error: ' + err)));
  });
}

async function initializeEarthEngine() {
  try {
    let keyObj = null;
    if (process.env.EE_PRIVATE_KEY && process.env.EE_CLIENT_EMAIL) {
      // Support setting key in env vars (useful for containers)
      keyObj = {
        private_key: process.env.EE_PRIVATE_KEY.replace(/\\n/g, '\n'),
        client_email: process.env.EE_CLIENT_EMAIL,
      };
    } else if (fs.existsSync(EE_KEY_FILE)) {
      keyObj = require(path.resolve(EE_KEY_FILE));
    } else {
      throw new Error('No Earth Engine credentials found. Set EE_KEY_FILE or EE_PRIVATE_KEY+EE_CLIENT_EMAIL');
    }

    await eeInitializeWithPrivateKey(keyObj);
    console.log('✅ Earth Engine initialized');
    return true;
  } catch (err) {
    console.error('❌ Earth Engine initialization failed:', err.message || err);
    throw err;
  }
}

// Helper to wrap callback-style getMap into a Promise
function getMapIdAsync(image, visParams) {
  return new Promise((resolve, reject) => {
    try {
      image.getMap(visParams, (mapIdObj, errorMessage) => {
        if (errorMessage) {
            reject(new Error(errorMessage));
        } else {
            resolve(mapIdObj);
        }
      });
    } catch (err) {
      reject(err);
    }
  });
}

// Cache helper using Redis (string keys)
async function cacheGet(key) {
  const v = await redis.get(key);
  if (!v) return null;
  try {
    return JSON.parse(v);
  } catch (e) {
    return v;
  }
}
async function cacheSet(key, value, ttl = CACHE_TTL) {
  await redis.set(key, JSON.stringify(value), 'EX', ttl);
}

// ----------------------------------------------------------------------
// SATELLITE PROCESSING LOGIC (Cloud Masking & Indices)
// ----------------------------------------------------------------------

function maskS2Clouds(image) {
  var qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  var cloudBitMask = 1 << 10;
  var cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000);
}

function maskLandsatClouds(image) {
  var qa = image.select('QA_PIXEL');
  // Bit 3 is cloud, bit 4 is cloud shadow
  var mask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
  return image.updateMask(mask)
      .select('SR_B.').multiply(0.0000275).add(-0.2); // Apply scaling factors
}

// ----------------------------------------------------------------------
// WORKER: PROCESS THE QUEUE
// ----------------------------------------------------------------------

ndviQueue.process(async (job) => {
    // 1. Validation & Setup
    if (!ee.data.getAuthToken()) {
        throw new Error('Earth Engine not initialized');
    }

    const { polygon, months } = job.data;
    if (!polygon) throw new Error('Polygon missing');

    const geometry = ee.Geometry(polygon);
    const end = ee.Date(new Date());
    const start = end.advance(-(months || 6), 'month');

    // 2. Fetch Sentinel-2 (High Revisit, 10m res)
    const s2 = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
        .filterBounds(geometry)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30)) // Less strict to allow partials
        .map(maskS2Clouds)
        .map(img => img.addBands(img.normalizedDifference(['B8', 'B4']).rename('NDVI')))
        .select(['NDVI']);

    // 3. Fetch Landsat 8 & 9 (30m res, fill gaps)
    const l9 = ee.ImageCollection("LANDSAT/LC09/C02/T1_L2")
        .filterBounds(geometry)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 30))
        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

    const l8 = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
        .filterBounds(geometry)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 30))
        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

    // 4. Merge Collections
    const collection = s2.merge(l9).merge(l8).sort('system:time_start');

    // 5. Reduce Region (Calculate Mean NDVI per Date)
    const timeSeries = collection.map(image => {
        const mean = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: geometry,
            scale: 20, // Compromise between S2 (10m) and L8 (30m) for speed
            maxPixels: 1e9
        });

        return ee.Feature(null, {
            'value': mean.get('NDVI'),
            'date': image.date().format('YYYY-MM-DD')
        });
    });

    // 6. Filter & Execute
    const resultFeatureCollection = timeSeries.filter(ee.Filter.notNull(['value']));

    // Evaluate runs asynchronously on Google servers and returns standard JSON
    return new Promise((resolve, reject) => {
        resultFeatureCollection.evaluate((data, error) => {
            if (error) {
                reject(new Error(error));
            } else {
                if (!data || !data.features) {
                    resolve([]);
                    return;
                }

                // Transform GeoJSON features to simple array
                const points = data.features
                    .map(f => ({
                        date: f.properties.date,
                        value: Number(f.properties.value.toFixed(3))
                    }))
                    // Filter outliers (clouds missed by mask)
                    .filter(p => p.value > 0.05 && p.value <= 1.0)
                    // Deduplicate dates (if multiple satellites passed same day, keep one)
                    .reduce((acc, current) => {
                        const exists = acc.find(item => item.date === current.date);
                        if (!exists) {
                            return acc.concat([current]);
                        }
                        return acc;
                    }, [])
                    .sort((a, b) => new Date(a.date) - new Date(b.date));

                resolve(points);
            }
        });
    });
});

// ----------------------------------------------------------------------
// EXPRESS SERVER SETUP
// ----------------------------------------------------------------------

// Express app setup
const app = express();
app.use(cors());
app.use(bodyParser.json({ limit: '2mb' }));

// Request Logger Middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

// Input validation helpers
function validatePolygon(coords) {
  if (!Array.isArray(coords)) throw new Error('polygon must be an array');
  // Basic size check
  let count = JSON.stringify(coords).length;
  if (count > 200000) throw new Error('polygon too large');
  return true;
}

// Build server routes
app.get('/', (req, res) => res.json({ message: 'Agrisense Node API OK' }));

// POST /api/get-layer
// body: { polygon: GeoJSON coordinates (Polygon or MultiPolygon), layer: 'ndvi'|'lst'|'elevation'|'soil'|'satellite' }
app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'satellite' } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    const cacheKey = `map:${layer}:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) {
        console.log(`Returning cached tile URL for ${layer}`);
        return res.json({ tile_url: cached });
    }

    // Convert coords to ee.Geometry
    const region = ee.Geometry(polygon);

    let mapImage = null;
    let vis = null;

    const end = ee.Date.now();
    const start60 = end.advance(-60, 'day');

    if (layer === 'ndvi') {
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));

      const image = collection.median().clip(region);
      mapImage = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      vis = { min: 0, max: 0.8, palette: ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'] };
    } else if (layer === 'lst') {
      const collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .sort('CLOUD_COVER');
      const image = collection.first().clip(region);
      const kelvin = image.select('ST_B10').multiply(0.00341802).add(149.0);
      mapImage = kelvin.subtract(273.15).rename('LST');
      vis = { min: 15, max: 35, palette: ['blue', 'yellow', 'red'] };
    } else if (layer === 'elevation') {
      mapImage = ee.Image('USGS/SRTMGL1_003').clip(region);
      vis = { min: 0, max: 2000 };
    } else if (layer === 'soil') {
      mapImage = ee.Image('OpenLandMap/SOL/SOL_CLAY-WFRACTION_USDA-3A1a1a_M/v02').select('b0').clip(region);
      vis = { min: 0, max: 60 };
    } else {
      // satellite RGB
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start60, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));
      const image = collection.median().clip(region);
      mapImage = image;
      vis = { bands: ['B4', 'B3', 'B2'], min: 0.0, max: 0.3 };
    }

    // Get tile URL asynchronously
    console.log(`Generating map for ${layer}...`);
    const mapid = await getMapIdAsync(mapImage, vis);

    let tileUrl = null;
    if (mapid) {
        if (mapid.urlFormat) {
            tileUrl = mapid.urlFormat;
        } else if (mapid.tile_fetcher && mapid.tile_fetcher.url_format) {
            tileUrl = mapid.tile_fetcher.url_format;
        } else if (mapid.mapid && mapid.token) {
            tileUrl = `https://earthengine.googleapis.com/map/${mapid.mapid}/{z}/{x}/{y}?token=${mapid.token}`;
        }
    }

    if (!tileUrl) throw new Error('Could not generate tile URL from Earth Engine response');

    console.log(`Generated URL: ${tileUrl}`);
    await cacheSet(cacheKey, tileUrl, 60);
    return res.json({ tile_url: tileUrl });
  } catch (err) {
    console.error('Error in /api/get-layer:', err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

// POST /api/get-stats -> enqueue job
app.post('/api/get-stats', async (req, res) => {
  try {
    const { polygon, months = 6 } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    console.log('Enqueuing stats job...');
    const job = await ndviQueue.add({ polygon, months }, { removeOnComplete: true, removeOnFail: false });
    return res.json({ jobId: job.id });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

// GET /api/job/:id -> status/result
app.get('/api/job/:id', async (req, res) => {
  try {
    const job = await ndviQueue.getJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'job not found' });
    const state = await job.getState();
    const result = await job.returnvalue; // may be undefined until finished
    return res.json({ id: job.id, state, result });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

// Start the server after EE initialization
initializeEarthEngine().then(() => {
  // Bind to 0.0.0.0 to listen on all interfaces (IPv4)
  app.listen(PORT, '0.0.0.0', () => {
    console.log(`🚀 Agrisense server listening on http://localhost:${PORT} (0.0.0.0)`);
  });
}).catch((err) => {
  console.error('Failed to initialize Earth Engine. Exiting.');
  console.error(err);
  process.exit(1);
});

