const ee = require('@google/earthengine');
const Queue = require('bull');
const fs = require('fs');
const path = require('path');
const IORedis = require('ioredis');

const REDIS_URL = process.env.REDIS_URL || 'redis://127.0.0.1:6379';
const EE_KEY_FILE = process.env.EE_KEY_FILE || './service-account-key.json';

const ndviQueue = new Queue('ndvi-jobs', REDIS_URL);

function eeInitializeWithPrivateKey(keyObj) {
  return new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(keyObj, () => {
      ee.initialize(null, null, () => resolve(), (err) => reject(err));
    }, (err) => reject(err));
  });
}

async function initializeEarthEngine() {
  let keyObj = null;
  if (process.env.EE_PRIVATE_KEY && process.env.EE_CLIENT_EMAIL) {
    keyObj = { private_key: process.env.EE_PRIVATE_KEY.replace(/\\n/g, '\n'), client_email: process.env.EE_CLIENT_EMAIL };
  } else if (fs.existsSync(EE_KEY_FILE)) {
    keyObj = require(path.resolve(EE_KEY_FILE));
  } else {
    throw new Error('No Earth Engine credentials found');
  }
  await eeInitializeWithPrivateKey(keyObj);
}

function computeNdviTimeSeries(polygon, months) {
  return new Promise((resolve, reject) => {
    try {
      const region = ee.Geometry(polygon);
      const end = ee.Date.now();
      const start = end.advance(-months, 'month');

      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));

      function calcNdvi(img) {
        const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
        const stats = ndvi.reduceRegion(ee.Reducer.mean(), region, 20, 1e9);
        return ee.Feature(null, { date: img.date().format('YYYY-MM-dd'), value: stats.get('NDVI') });
      }

      const timeSeries = collection.map(calcNdvi).filter(ee.Filter.notNull(['value']));

      // getInfo will fetch server-side results
      timeSeries.getInfo((infoErr, info) => {
        if (infoErr) return reject(infoErr);
        const feats = info.features || [];
        const results = feats.map((f) => ({ date: f.properties.date, value: Math.round((f.properties.value || 0) * 1000) / 1000 }));
        results.sort((a, b) => a.date.localeCompare(b.date));
        resolve(results);
      });

    } catch (err) {
      reject(err);
    }
  });
}

(async () => {
  try {
    await initializeEarthEngine();
    console.log('Worker: Earth Engine initialized');

    ndviQueue.process(async (job) => {
      console.log('Worker: processing job', job.id);
      const { polygon, months } = job.data;
      const result = await computeNdviTimeSeries(polygon, months || 6);
      return result;
    });

    ndviQueue.on('completed', (job, result) => {
      console.log('Job completed', job.id);
    });

    ndviQueue.on('failed', (job, err) => {
      console.error('Job failed', job.id, err);
    });

  } catch (err) {
    console.error('Worker init failed', err);
    process.exit(1);
  }
})();

