app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'satellite' } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    const cacheKey = `map:${layer}:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) {
        console.log(`Returning cached tile URL for ${layer}`);
        return res.json({ tile_url: cached });
    }

    // Convert coords to ee.Geometry
    const region = ee.Geometry(polygon);

    let mapImage = null;
    let vis = null;

    const end = ee.Date.now();
    const start60 = end.advance(-60, 'day');

    if (layer === 'ndvi') {
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));

      const image = collection.median().clip(region);
      mapImage = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      vis = { min: 0, max: 0.8, palette: ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'] };
    } else if (layer === 'lst') {
      const collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .sort('CLOUD_COVER');
      const image = collection.first().clip(region);
      const kelvin = image.select('ST_B10').multiply(0.00341802).add(149.0);
      mapImage = kelvin.subtract(273.15).rename('LST');
      vis = { min: 15, max: 35, palette: ['blue', 'yellow', 'red'] };
    } else if (layer === 'elevation') {
      mapImage = ee.Image('USGS/SRTMGL1_003').clip(region);
      vis = { min: 0, max: 2000 };
    } else if (layer === 'soil') {
      mapImage = ee.Image('OpenLandMap/SOL/SOL_CLAY-WFRACTION_USDA-3A1a1a_M/v02').select('b0').clip(region);
      vis = { min: 0, max: 60 };
    } else {
      // satellite RGB
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start60, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));
      const image = collection.median().clip(region);
      mapImage = image;
      vis = { bands: ['B4', 'B3', 'B2'], min: 0.0, max: 0.3 };
    }

