// --- CLOUD MASKING HELPERS ---

function maskS2Clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
    .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000);
}

function maskLandsatClouds(image) {
  const qa = image.select('QA_PIXEL');
  // Bit 3 is cloud, bit 4 is cloud shadow
  const mask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
  return image.updateMask(mask)
      .select('SR_B.').multiply(0.0000275).add(-0.2); // Scale factors
}

function computeNdviTimeSeries(polygon, months) {
  return new Promise((resolve, reject) => {
    try {
      const region = ee.Geometry(polygon);
      const end = ee.Date.now();
      const start = end.advance(-months, 'month');

      // 1. Sentinel-2
      const s2 = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 40))
        .map(maskS2Clouds)
        .map(img => img.addBands(img.normalizedDifference(['B8', 'B4']).rename('NDVI')))
        .select(['NDVI']);

      // 2. Landsat 9
      const l9 = ee.ImageCollection("LANDSAT/LC09/C02/T1_L2")
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 40))
        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

      // 3. Landsat 8
      const l8 = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 40))
        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

      // 4. Merge
      const collection = s2.merge(l9).merge(l8).sort('system:time_start');

      const timeSeries = collection.map(image => {
        const mean = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: region,
            scale: 20, 
            maxPixels: 1e9
        });
        return ee.Feature(null, {
            'value': mean.get('NDVI'),
            'date': image.date().format('YYYY-MM-DD')
        });
      }).filter(ee.Filter.notNull(['value']));

      // 5. Evaluate (Cleaner than getInfo)
      timeSeries.evaluate((data, error) => {
        if (error) {
            reject(new Error(error));
        } else {
            if (!data || !data.features) {
                resolve([]);
                return;
            }

            // Post-processing: dedup & sort
            const points = data.features
                .map(f => ({
                    date: f.properties.date,
                    value: Number(f.properties.value.toFixed(3))
                }))
                .filter(p => p.value > 0.05 && p.value <= 1.0)
                .reduce((acc, current) => {
                    const exists = acc.find(item => item.date === current.date);
                    if (!exists) return acc.concat([current]);
                    return acc;
                }, [])
                .sort((a, b) => new Date(a.date) - new Date(b.date));

            resolve(points);
        }
      });

    } catch (err) {
      reject(err);
    }
  });
}

(async () => {
  try {
    await initializeEarthEngine();
    console.log('Worker: Earth Engine initialized');

    ndviQueue.process(async (job) => {
      console.log('Worker: processing job', job.id);
      const { polygon, months } = job.data;
      const result = await computeNdviTimeSeries(polygon, months || 6);
      return result;
    });

    ndviQueue.on('completed', (job, result) => {
      console.log('Job completed', job.id);
    });

    ndviQueue.on('failed', (job, err) => {
      console.error('Job failed', job.id, err);
    });

  } catch (err) {
    console.error('Worker init failed', err);
    process.exit(1);
  }
})();

