// Input validation helpers
function validatePolygon(coords) {
  if (!Array.isArray(coords)) throw new Error('polygon must be an array');
  // Basic size check
  let count = JSON.stringify(coords).length;
  if (count > 200000) throw new Error('polygon too large');
