}

// Build server routes
app.get('/', (req, res) => res.json({ message: 'Agrisense Node API OK' }));

// POST /api/get-layer
// body: { polygon: GeoJSON coordinates (Polygon or MultiPolygon), layer: 'ndvi'|'lst'|'elevation'|'soil'|'satellite' }
app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'satellite' } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    const cacheKey = `map:${layer}:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) {
        console.log(`Returning cached tile URL for ${layer}`);
        return res.json({ tile_url: cached });
    }

    // Convert coords to ee.Geometry
    const region = ee.Geometry(polygon);

    let mapImage = null;
    let vis = null;

    const end = ee.Date.now();
    const start60 = end.advance(-60, 'day');

    if (layer === 'ndvi') {
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));

      const image = collection.median().clip(region);
      mapImage = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      vis = { min: 0, max: 0.8, palette: ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'] };
    } else if (layer === 'lst') {
      const collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(region)
        .filterDate(end.advance(-90, 'day'), end)
        .sort('CLOUD_COVER');
      const image = collection.first().clip(region);
      const kelvin = image.select('ST_B10').multiply(0.00341802).add(149.0);
      mapImage = kelvin.subtract(273.15).rename('LST');
      vis = { min: 15, max: 35, palette: ['blue', 'yellow', 'red'] };
    } else if (layer === 'elevation') {
      mapImage = ee.Image('USGS/SRTMGL1_003').clip(region);
      vis = { min: 0, max: 2000 };
    } else if (layer === 'soil') {
      mapImage = ee.Image('OpenLandMap/SOL/SOL_CLAY-WFRACTION_USDA-3A1a1a_M/v02').select('b0').clip(region);
      vis = { min: 0, max: 60 };
    } else {
      // satellite RGB
      const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start60, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000));
      const image = collection.median().clip(region);
      mapImage = image;
      vis = { bands: ['B4', 'B3', 'B2'], min: 0.0, max: 0.3 };
    }

    // Get tile URL asynchronously
    console.log(`Generating map for ${layer}...`);
    const mapid = await getMapIdAsync(mapImage, vis);

    let tileUrl = null;
    if (mapid) {
        if (mapid.urlFormat) {
            tileUrl = mapid.urlFormat;
        } else if (mapid.tile_fetcher && mapid.tile_fetcher.url_format) {
            tileUrl = mapid.tile_fetcher.url_format;
        } else if (mapid.mapid && mapid.token) {
            tileUrl = `https://earthengine.googleapis.com/map/${mapid.mapid}/{z}/{x}/{y}?token=${mapid.token}`;
        }
    }

    if (!tileUrl) throw new Error('Could not generate tile URL from Earth Engine response');

    console.log(`Generated URL: ${tileUrl}`);
    await cacheSet(cacheKey, tileUrl, 60);
    return res.json({ tile_url: tileUrl });
  } catch (err) {
    console.error('Error in /api/get-layer:', err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

// POST /api/get-stats -> enqueue job
app.post('/api/get-stats', async (req, res) => {
  try {
    const { polygon, months = 6 } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    console.log('Enqueuing stats job...');
    const job = await ndviQueue.add({ polygon, months }, { removeOnComplete: true, removeOnFail: false });
    return res.json({ jobId: job.id });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

// GET /api/job/:id -> status/result
app.get('/api/job/:id', async (req, res) => {
  try {
    const job = await ndviQueue.getJob(req.params.id);
    if (!job) return res.status(404).json({ error: 'job not found' });
    const state = await job.getState();
    const result = await job.returnvalue; // may be undefined until finished
    return res.json({ id: job.id, state, result });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

