// 2. Get Statistics (Job Queue + Polling)
// ----------------------------------------------------------------------
export interface GeeTimeSeriesPoint {
    date: string;
    value: number;
}

export const fetchGeeTimeSeries = async (
    boundary: any,
    backendUrl: string
): Promise<GeeTimeSeriesPoint[] | null> => {
    if (isSimulationMode()) {
        console.log("Simulation Mode: Returning mock time series.");
        await new Promise(r => setTimeout(r, 800)); // Fake network delay
        // We use a generic start date (6 months ago) and default crop
        const today = new Date();
        const start = new Date();
        start.setMonth(today.getMonth() - 6);
        return generateMockNdviHistory(start.toISOString().split('T')[0], 'Winter Wheat');
    }

    try {
        console.log(`Starting stats job on ${backendUrl}...`);
        const polygon = formatPolygonForBackend(boundary);
        const endpoint = `${backendUrl}/api/get-stats`;

        // Step 1: Submit Job
        let enqueueRes;
        try {
            enqueueRes = await fetch(endpoint, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ polygon, months: 6 })
            });
        } catch (netErr: any) {
            console.error("Network Error Details:", netErr);
            throw new Error(`Could not connect to ${backendUrl}. If using HTTPS, ensure Mixed Content is allowed, or run the server on HTTPS.`);
        }

        if (!enqueueRes.ok) {
            const txt = await enqueueRes.text();
            throw new Error(`Server Error (${enqueueRes.status}): ${txt}`);
        }
        const { jobId } = await enqueueRes.json();
        console.log(`Job enqueued: ${jobId}. Polling for results...`);

        // Step 2: Poll for Completion
        const maxAttempts = 40; 
        const baseInterval = 1000;

        for (let i = 0; i < maxAttempts; i++) {
            // Exponential Backoff: 1s, 1.2s, 1.44s ... capped at 5s wait per poll
            const waitTime = Math.min(5000, baseInterval * Math.pow(1.2, i));
            await new Promise(r => setTimeout(r, waitTime));

            const jobRes = await fetch(`${backendUrl}/api/job/${jobId}`);
            if (!jobRes.ok) continue; // If network glitch, retry loop

            const jobData = await jobRes.json();

            if (jobData.state === 'completed') {
                console.log("Job completed successfully", jobData.result);
                return jobData.result;
            }
            if (jobData.state === 'failed') {
                console.error("Job failed on backend");
                return null;
            }
            // If 'active' or 'queued', we continue the loop
        }

        throw new Error("Job timed out while waiting for Earth Engine.");

    } catch (error) {
        console.error("GEE Stats Error:", error);
        throw error;
    }
};

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useParcels, Parcel } from '../context/ParcelContext';
import { fetchFieldWeather, WeatherData, getWeatherLabel, getCoordinates } from '../utils/weatherService';
import { generateMockNdviHistory, NdviPoint, getNdviColor } from '../utils/ndviService';
import { getApiKey } from '../utils/agromonitoring.ts';
import { getBackendUrl, fetchGeeLayer, fetchGeeTimeSeries } from '../utils/geeService';
import { ArrowLeft, Wind, Droplets, Thermometer, CloudRain, Sun, Cloud, CloudLightning, Snowflake, Calendar, MapPin, Sprout, Navigation, Layers, Satellite, Activity, Info, AlertTriangle, Settings as SettingsIcon, Mountain, FlaskConical, RefreshCw, Server, Save, Cloud as CloudIcon, Database, XCircle, Zap } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Bar, ComposedChart, Line, LineChart, ReferenceLine } from 'recharts';

export const FieldDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { parcels, updateParcel } = useParcels();
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [loading, setLoading] = useState(true);

  // Data State
  const [ndviHistory, setNdviHistory] = useState<NdviPoint[]>([]);
  const [loadingStats, setLoadingStats] = useState(false);
  const [dataSource, setDataSource] = useState<'mock' | 'gee' | 'saved' | 'simulated'>('mock');
  const [backendError, setBackendError] = useState<string | null>(null);

  // Check Simulation Mode
  const isSimulation = localStorage.getItem('gee_simulation_mode') === 'true';

  // Find the parcel
  const parcel = parcels.find(p => p.id === id);

  // Helper to fetch GEE data and save it
  const fetchAndSaveStats = async (currentParcel: Parcel) => {
      if (!currentParcel.boundary) return;

      setLoadingStats(true);
      setBackendError(null); // Reset error

      try {
          const backendUrl = getBackendUrl();
          // Use the service which now handles timeouts and errors gracefully (or returns mock if simulation is on)
          const realData = await fetchGeeTimeSeries(currentParcel.boundary, backendUrl);

          if (realData && realData.length > 0) {
              setNdviHistory(realData);

              if (isSimulation) {
                  setDataSource('simulated');
              } else {
                  setDataSource('gee');
                  // Only cache if it's REAL data, not simulation
                  await updateParcel(currentParcel.id, { 
                      ndviHistory: realData,
                      lastAgroSync: Date.now() 
                  });
              }
          } else {
              // Only here if the backend returned empty data but NO error
              console.warn("Backend returned empty data");
              if (currentParcel.ndviHistory && currentParcel.ndviHistory.length > 0) {
                  setNdviHistory(currentParcel.ndviHistory);
                  setDataSource('saved');
              } else {
                  setNdviHistory(generateMockNdviHistory(currentParcel.date, currentParcel.crop));
                  setDataSource('mock');
              }
          }
      } catch(e: any) {
          console.error("GEE Connection Failed:", e);
          setBackendError(e.message || "Failed to connect to backend server.");

          // Fallback logic, but we keep the error visible
          if (currentParcel.ndviHistory && currentParcel.ndviHistory.length > 0) {
               setNdviHistory(currentParcel.ndviHistory);
               setDataSource('saved');
          } else {
               setNdviHistory(generateMockNdviHistory(currentParcel.date, currentParcel.crop));
               setDataSource('mock');
          }
      }
      setLoadingStats(false);
  };

  useEffect(() => {
    const initData = async () => {
        if (!parcel) return;

        const { lat, lng } = getCoordinates(parcel.location);

        // 1. Load Weather
        fetchFieldWeather(lat, lng)
            .then(data => {
                setWeather(data);
                setLoading(false);
            })
            .catch((err) => {
                console.warn("Weather load failed:", err);
                setLoading(false);
            });

        // 2. Load Stats
        // Check if we have saved data first (Fast Load)
        if (parcel.ndviHistory && parcel.ndviHistory.length > 0 && !isSimulation) {
            setNdviHistory(parcel.ndviHistory);
            setDataSource('saved');
        } else {
            // If no data or simulation mode, try to fetch (fetch handles simulation internally)
            fetchAndSaveStats(parcel);
        }
    };

    initData();
  }, [parcel?.id]); 

  if (!parcel) {
    return (
      <div className="flex flex-col items-center justify-center h-full space-y-4">
        <h2 className="text-xl font-bold text-gray-800">Field Not Found</h2>
        <button onClick={() => navigate('/dashboard')} className="text-emerald-600 hover:underline">Return to Dashboard</button>
      </div>
    );
  }

  const getWeatherIcon = (code: number, size = 32) => {
    if (code === 0 || code === 1) return <Sun className="text-amber-500" size={size} />;
    if (code === 2 || code === 3) return <Cloud className="text-gray-500" size={size} />;
    if (code >= 51 && code <= 67) return <CloudRain className="text-blue-400" size={size} />;
    if (code >= 71 && code <= 77) return <Snowflake className="text-cyan-400" size={size} />;
    if (code >= 95) return <CloudLightning className="text-purple-500" size={size} />;
    return <Cloud className="text-gray-400" size={size} />;
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-DK', { weekday: 'short', day: 'numeric' }).format(date);
  };

  const formatShortDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-DK', { weekday: 'short' }).format(date);
  };

  const getCardinalDirection = (deg: number) => {
    const val = Math.floor((deg / 22.5) + 0.5);
    const arr = ["N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW"];
    return arr[val % 16];
  };

