        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

      // 3. Landsat 8
      const l8 = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUD_COVER', 40))
        .map(maskLandsatClouds)
        .map(img => img.addBands(img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI')))
        .select(['NDVI']);

      const collection = s2.merge(l9).merge(l8).sort('system:time_start');

      const timeSeries = collection.map(image => {
        const mean = image.reduceRegion({
            reducer: ee.Reducer.mean(),
            geometry: region,
            scale: 20, 
            maxPixels: 1e9
        });
        return ee.Feature(null, {
            'value': mean.get('NDVI'),
            'date': image.date().format('YYYY-MM-DD')
        });
      }).filter(ee.Filter.notNull(['value']));

      timeSeries.evaluate((data, error) => {
        if (error) {
            reject(new Error(error));
        } else {
            if (!data || !data.features) {
                resolve([]);
                return;
            }
            const points = data.features
                .map(f => ({
                    date: f.properties.date,
                    value: Number(f.properties.value.toFixed(3))
                }))
                .filter(p => p.value > 0.05 && p.value <= 1.0)
                .reduce((acc, current) => {
                    const exists = acc.find(item => item.date === current.date);
                    if (!exists) return acc.concat([current]);
                    return acc;
                }, [])
                .sort((a, b) => new Date(a.date) - new Date(b.date));

            resolve(points);
        }
      });

    } catch (err) {
      reject(err);
    }
  });
}

(async () => {
  try {
    await initializeEarthEngine();
    console.log('Worker: Earth Engine initialized');

    ndviQueue.process(async (job) => {
      console.log('Worker: processing job', job.id);
      const { polygon, months, startDate, endDate } = job.data;
      const result = await computeNdviTimeSeries(polygon, months, startDate, endDate);
      return result;
    });

    ndviQueue.on('completed', (job, result) => {
      console.log('Job completed', job.id);
    });

    ndviQueue.on('failed', (job, err) => {
      console.error('Job failed', job.id, err);
    });

  } catch (err) {
    console.error('Worker init failed', err);
    process.exit(1);
  }
})();

