        } />

        <Route path="/globe" element={
          <PrivateRoute>
            <GlobePage />
          </PrivateRoute>
        } />

        <Route path="/settings" element={
          <PrivateRoute>
            <Settings />
          </PrivateRoute>
        } />
      </Routes>
    </HashRouter>
  );
};

