export const GlobePage: React.FC = () => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstanceRef = useRef<any>(null);
    const { parcels } = useParcels();
    const [heading, setHeading] = useState(0);
    const [tilt, setTilt] = useState(45);
    const [showParcels, setShowParcels] = useState(true);

    useEffect(() => {
        if (!mapRef.current || !window.google) return;
        if (mapInstanceRef.current) return;

        // "DEMO_MAP_ID" enables vector map features including WebGL 3D buildings and smoother tilt/heading
        // This provides the "Google Earth" experience within the JS API.
        const map = new window.google.maps.Map(mapRef.current, {
            center: { lat: 56.2639, lng: 9.5018 },
            zoom: 6,
            mapId: "DEMO_MAP_ID", 
            mapTypeId: 'satellite',
            tilt: 45,
            heading: 0,
            disableDefaultUI: true,
            zoomControl: false,
            rotateControl: false,
            scaleControl: true,
            streetViewControl: false,
            // Enable 3D buildings (beta feature in some versions, but mapId usually enables it)
        });

        mapInstanceRef.current = map;

        // Listen to map changes to update UI controls
        map.addListener('heading_changed', () => {
            setHeading(map.getHeading() || 0);
        });
        map.addListener('tilt_changed', () => {
            setTilt(map.getTilt() || 0);
        });

    }, []);

    // Render Parcels on the Globe
    useEffect(() => {
        if (!mapInstanceRef.current || !window.google) return;

        // Clear existing (if we were tracking them, but for now we just re-render or let them persist)
        // For a simple implementation, we just add them. In production, we'd clean up markers.

        if (showParcels) {
            parcels.forEach(p => {
                if(p.boundary) {
                    // Draw Polygon
                    new window.google.maps.Polygon({
                        paths: p.boundary,
                        strokeColor: '#34d399',
                        strokeOpacity: 0.9,
                        strokeWeight: 2,
                        fillColor: '#10b981',
                        fillOpacity: 0.4,
                        map: mapInstanceRef.current
                    });

                    // Add a Marker for clicking/label
                    const bounds = new window.google.maps.LatLngBounds();
                    const paths = Array.isArray(p.boundary[0]) ? p.boundary.flat() : p.boundary;
                    paths.forEach((pt: any) => bounds.extend(pt));
                    const center = bounds.getCenter();

                    const marker = new window.google.maps.Marker({
                        position: center,
                        map: mapInstanceRef.current,
                        title: p.name,
                        label: {
                            text: p.name,
                            color: 'white',
                            className: 'bg-black/50 px-2 py-1 rounded text-xs font-bold',
                            fontSize: '12px'
                        },
                        icon: {
                            path: window.google.maps.SymbolPath.CIRCLE,
                            scale: 0
                        }
                    });

                    marker.addListener('click', () => {
                        flyTo(center, 16, 45, 0);
                    });
                }
            });
        }
    }, [parcels, showParcels]);

    const flyTo = (location: any, zoom: number, tilt: number, heading: number) => {
        if (!mapInstanceRef.current) return;

        // Use moveCamera for smooth 3D transition
        mapInstanceRef.current.moveCamera({
            center: location,
            zoom: zoom,
            tilt: tilt,
            heading: heading
        });
    };

    const handleZoom = (delta: number) => {
        if (!mapInstanceRef.current) return;
        mapInstanceRef.current.setZoom((mapInstanceRef.current.getZoom() || 10) + delta);
    };

    const handleRotate = (delta: number) => {
        if (!mapInstanceRef.current) return;
        const newHeading = (mapInstanceRef.current.getHeading() || 0) + delta;
        mapInstanceRef.current.setHeading(newHeading);
    };

    const handleTilt = () => {
        if (!mapInstanceRef.current) return;
        const currentTilt = mapInstanceRef.current.getTilt();
        mapInstanceRef.current.setTilt(currentTilt > 20 ? 0 : 45);
    };

    return (
        <div className="h-full w-full relative rounded-xl overflow-hidden shadow-sm border border-gray-200 bg-gray-900">

           {/* The Map */}
           <div ref={mapRef} className="absolute inset-0 z-0" />

           {/* Top Right Controls (Navigation) */}
           <div className="absolute top-4 right-4 flex flex-col gap-2 z-10">
               {/* Zoom Group */}
               <div className="bg-white/90 backdrop-blur rounded-lg shadow border border-gray-200 flex flex-col overflow-hidden">
                   <button onClick={() => handleZoom(1)} className="p-2 hover:bg-gray-100 text-gray-700 border-b border-gray-200" title="Zoom In">
                       <Plus size={20} />
                   </button>
                   <button onClick={() => handleZoom(-1)} className="p-2 hover:bg-gray-100 text-gray-700" title="Zoom Out">
                       <Minus size={20} />
                   </button>
               </div>

               {/* Orientation Group */}
               <div className="bg-white/90 backdrop-blur rounded-lg shadow border border-gray-200 flex flex-col overflow-hidden mt-2">
                   <button onClick={() => handleTilt()} className="p-2 hover:bg-gray-100 text-gray-700 border-b border-gray-200" title="Toggle 3D Tilt">
                       <Layers size={20} className={tilt > 0 ? "text-emerald-600" : "text-gray-400"} />
                   </button>
                   <button onClick={() => handleRotate(-45)} className="p-2 hover:bg-gray-100 text-gray-700 border-b border-gray-200" title="Rotate Left">
                       <RotateCcw size={20} />
                   </button>
                   <button onClick={() => handleRotate(45)} className="p-2 hover:bg-gray-100 text-gray-700" title="Rotate Right">
                       <RotateCw size={20} />
                   </button>
               </div>

               {/* Compass Indicator */}
               <div 
                 className="bg-white/90 backdrop-blur rounded-full shadow border border-gray-200 p-2 mt-2 flex items-center justify-center cursor-pointer hover:bg-gray-50 transition-transform duration-500"
                 style={{ transform: `rotate(${heading}deg)` }}
                 onClick={() => {
                     if(mapInstanceRef.current) {
                         mapInstanceRef.current.setHeading(0);
                         mapInstanceRef.current.setTilt(0);
                     }
                 }}
                 title="Reset North"
               >
                   <Compass size={24} className="text-red-600" />
               </div>
           </div>

           {/* Left Sidebar: Places */}
           <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-2rem)] flex flex-col gap-4">

               <div className="bg-white/90 backdrop-blur p-4 rounded-xl shadow-lg border border-gray-200 w-64">
                   <h3 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-2">
                       <MapPin size={16} className="text-emerald-600"/> My Places
                   </h3>

                   {parcels.length === 0 ? (
                       <p className="text-xs text-gray-500 italic">No fields defined yet.</p>
                   ) : (
                       <div className="space-y-1 max-h-60 overflow-y-auto pr-1">
                           {parcels.map(p => (
                               <button 
                                   key={p.id}
                                   onClick={() => {
                                        const bounds = new window.google.maps.LatLngBounds();
                                        const paths = Array.isArray(p.boundary![0]) ? p.boundary!.flat() : p.boundary;
                                        paths.forEach((pt: any) => bounds.extend(pt));
                                        flyTo(bounds.getCenter(), 17, 60, heading);
                                   }}
                                   className="w-full text-left px-3 py-2 text-xs font-medium text-gray-700 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg transition-colors flex items-center justify-between group"
                               >
                                   <span>{p.name}</span>
                                   <Locate size={12} className="opacity-0 group-hover:opacity-100 transition-opacity"/>
                               </button>
                           ))}
                       </div>
                   )}
               </div>

               {/* Instructions */}
               <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl text-white text-xs shadow-lg border border-white/10 w-64">
                   <h4 className="font-bold mb-2 flex items-center gap-2 text-emerald-400">
                       <MousePointer2 size={14} /> 3D Controls
                   </h4>
                   <ul className="space-y-1.5 opacity-90">
