import React, { useEffect, useRef, useState } from 'react';
import { useParcels, Parcel } from '../context/ParcelContext';
import { Compass, Locate, MousePointer2, MapPin, Layers } from 'lucide-react';

declare global {
  interface Window {
    Cesium: any;
  }
}

export const GlobePage: React.FC = () => {
    const cesiumContainer = useRef<HTMLDivElement>(null);
    const viewerRef = useRef<any>(null);
    const { parcels } = useParcels();
    const [cesiumLoaded, setCesiumLoaded] = useState(false);

    // Initialize Cesium
    useEffect(() => {
        if (!cesiumContainer.current || !window.Cesium) return;
        if (viewerRef.current) return;

        // NOTE: Ideally, you should set your Cesium Ion Access Token here for highest res imagery.
        // window.Cesium.Ion.defaultAccessToken = 'YOUR_TOKEN_HERE';

        const viewer = new window.Cesium.Viewer(cesiumContainer.current, {
            terrainProvider: window.Cesium.createWorldTerrain(),
            animation: false,
            timeline: false,
            baseLayerPicker: true,
            geocoder: true,
            homeButton: true,
            sceneModePicker: true,
            navigationHelpButton: false,
            fullscreenButton: false,
            infoBox: false, // We'll handle clicks ourselves or use default simple selection
            selectionIndicator: true
        });

        // Add 3D Buildings (OSM)
        const buildingsTileset = viewer.scene.primitives.add(window.Cesium.createOsmBuildings());

        // Settings for high quality rendering
        viewer.scene.globe.depthTestAgainstTerrain = true;
        viewer.scene.highDynamicRange = true;

        viewerRef.current = viewer;
        setCesiumLoaded(true);

        // Cleanup
        return () => {
            if (viewerRef.current) {
                viewerRef.current.destroy();
                viewerRef.current = null;
            }
        };
    }, []);

    // Render Parcels on the Globe
    useEffect(() => {
        if (!viewerRef.current || !cesiumLoaded) return;

        const viewer = viewerRef.current;

        // Clear previous entities to avoid duplicates if context changes
        viewer.entities.removeAll();

        parcels.forEach(p => {
            if(p.boundary) {
                // Handle both simple Polygon and MultiPolygon structure from context
                const rings = Array.isArray(p.boundary[0]) ? p.boundary : [p.boundary];

                // @ts-ignore
                rings.forEach((ring: any[]) => {
                    // Convert {lat, lng} objects to flat array [lng, lat, lng, lat...] for Cesium
                    const positions: number[] = [];
                    ring.forEach(pt => {
                        positions.push(pt.lng);
                        positions.push(pt.lat);
                    });

                    viewer.entities.add({
                        name: p.name,
                        description: `
                            <div style="padding:10px;">
                                <h3>${p.name}</h3>
                                <p>Crop: ${p.crop}</p>
                                <p>Size: ${p.size} ha</p>
                            </div>
                        `,
                        polygon: {
                            hierarchy: window.Cesium.Cartesian3.fromDegreesArray(positions),
                            height: 0, // Clamped to ground/terrain? If terrain on, this might clip. 
                            // Better to use classification type for draping, or set height relative to terrain.
                            // For simplicity, we use material and let it drape or sit at 0 altitude if 2D.
                            // However, strictly "on terrain" usually requires ClassificationType.

                            // Using a material that is slightly transparent green
                            material: window.Cesium.Color.fromCssColorString('#10b981').withAlpha(0.5),
                            outline: true,
                            outlineColor: window.Cesium.Color.fromCssColorString('#065f46'),
                            outlineWidth: 2,
                            classificationType: window.Cesium.ClassificationType.TERRAIN // Drapes polygon over terrain
                        },
                        // Add a pin at the center
                        position: window.Cesium.Cartesian3.fromDegrees(ring[0].lng, ring[0].lat), // Approximate center logic simplified
                        point: {
                            pixelSize: 0, // Hidden point, just for label anchor
                        },
                        label: {
                            text: p.name,
                            font: '14px sans-serif',
                            fillColor: window.Cesium.Color.WHITE,
                            outlineColor: window.Cesium.Color.BLACK,
                            outlineWidth: 2,
                            style: window.Cesium.LabelStyle.FILL_AND_OUTLINE,
                            verticalOrigin: window.Cesium.VerticalOrigin.BOTTOM,
                            pixelOffset: new window.Cesium.Cartesian2(0, -10),
                            distanceDisplayCondition: new window.Cesium.DistanceDisplayCondition(0.0, 50000.0)
                        }
                    });
                });
            }
        });

    }, [parcels, cesiumLoaded]);

    const flyToParcel = (parcel: Parcel) => {
        if (!viewerRef.current || !parcel.boundary) return;

        // Extract all points to calculate bounding box
        const points: any[] = [];
        const rings = Array.isArray(parcel.boundary[0]) ? parcel.boundary : [parcel.boundary];
        // @ts-ignore
        rings.forEach(ring => ring.forEach(pt => points.push(pt.lng, pt.lat)));

        const rectangle = window.Cesium.Rectangle.fromCartesianArray(
            window.Cesium.Cartesian3.fromDegreesArray(points)
        );

        viewerRef.current.camera.flyTo({
            destination: rectangle,
            orientation: {
                heading: window.Cesium.Math.toRadians(0.0),
                pitch: window.Cesium.Math.toRadians(-45.0), // 45 degree viewing angle like Google Earth
                roll: 0.0
            },
            duration: 2 // seconds
        });
    };

    return (
        <div className="h-full w-full relative rounded-xl overflow-hidden shadow-sm border border-gray-200 bg-gray-900">

           {/* Cesium Map Container */}
           <div ref={cesiumContainer} className="absolute inset-0 z-0" />

           {/* Left Sidebar: Places */}
           <div className="absolute top-4 left-4 z-10 max-h-[calc(100%-2rem)] flex flex-col gap-4">

               <div className="bg-white/90 backdrop-blur p-4 rounded-xl shadow-lg border border-gray-200 w-64">
                   <h3 className="text-sm font-bold text-gray-900 mb-3 flex items-center gap-2">
                       <MapPin size={16} className="text-emerald-600"/> My Places
                   </h3>

                   {parcels.length === 0 ? (
                       <p className="text-xs text-gray-500 italic">No fields defined yet.</p>
                   ) : (
                       <div className="space-y-1 max-h-60 overflow-y-auto pr-1">
                           {parcels.map(p => (
                               <button 
                                   key={p.id}
                                   onClick={() => flyToParcel(p)}
                                   className="w-full text-left px-3 py-2 text-xs font-medium text-gray-700 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg transition-colors flex items-center justify-between group"
                               >
                                   <span>{p.name}</span>
                                   <Locate size={12} className="opacity-0 group-hover:opacity-100 transition-opacity"/>
                               </button>
                           ))}
                       </div>
                   )}
               </div>

               {/* Instructions */}
               <div className="bg-black/60 backdrop-blur-md p-3 rounded-xl text-white text-xs shadow-lg border border-white/10 w-64">
                   <h4 className="font-bold mb-2 flex items-center gap-2 text-emerald-400">
                       <MousePointer2 size={14} /> Navigation
                   </h4>
                   <ul className="space-y-1.5 opacity-90">
                       <li className="flex items-center gap-2">
                           <span className="bg-white/20 px-1.5 rounded text-[10px]">Left Click</span>
                           <span>Pan</span>
                       </li>
                       <li className="flex items-center gap-2">
                           <span className="bg-white/20 px-1.5 rounded text-[10px]">Right Click</span>
                           <span>Zoom</span>
                       </li>
                       <li className="flex items-center gap-2">
                           <span className="bg-white/20 px-1.5 rounded text-[10px]">Wheel Click</span>
                           <span>Tilt / Rotate</span>
                       </li>
                       <li className="flex items-center gap-2">
                           <span className="bg-white/20 px-1.5 rounded text-[10px]">Ctrl + Drag</span>
                           <span>Tilt</span>
                       </li>
                   </ul>
               </div>
           </div>
        </div>
    );
};

