    useEffect(() => {
        if (!cesiumContainer.current || !window.Cesium) return;
        if (viewerRef.current) return;

        const initCesium = async () => {
            // 1. Set the Cesium Ion Access Token
            window.Cesium.Ion.defaultAccessToken = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJqdGkiOiIxOTZhN2M5Mi0wMjE0LTQ4NzEtOWJiMC1mNmIzM2MxMDQ3YTYiLCJpZCI6MzY5MTU4LCJpYXQiOjE3NjU1NDE1NTR9.WbGORKlqdnNJOWekIdOZDul1E0bow0viBJR7bPtcsdM";

            // 2. Initialize Viewer with World Terrain
            // Using standard options, enabling baseLayerPicker for fallback imagery
            const viewer = new window.Cesium.Viewer(cesiumContainer.current, {
                terrain: window.Cesium.Terrain.fromWorldTerrain(),
                animation: false,
                timeline: false,
                baseLayerPicker: true, 
                geocoder: true, 
                homeButton: true,
                sceneModePicker: true,
                navigationHelpButton: false,
                fullscreenButton: false,
                infoBox: false, 
                selectionIndicator: true
            });

            // 3. Load Google Photorealistic 3D Tiles
            try {
                // Remove default imagery layers so the Google 3D Tiles are the primary base
                // NOTE: If the key is invalid, this might result in a black globe. 
                // However, user requested Google 3D tiles specifically.
                viewer.imageryLayers.removeAll();

                const tileset = await window.Cesium.createGooglePhotorealistic3DTileset({
                    key: "AIzaSyASXghOIHCx0l-rPJ_F89LUlHp0uD7OF3o",
                });
                viewer.scene.primitives.add(tileset);

                // Reset camera view to home to ensure globe is in view
                viewer.camera.flyHome(0);

            } catch (error) {
                console.error("Failed to load Google 3D Tiles:", error);
                // If Google tiles fail, we might be staring at a black globe because we removed imagery layers.
                // We could try to add a default back, but for now we log the error.
            }

            // Enable depth testing
            viewer.scene.globe.depthTestAgainstTerrain = true;

            viewerRef.current = viewer;
            setCesiumLoaded(true);
        };

        initCesium();

        // Cleanup
        return () => {
            if (viewerRef.current) {
                viewerRef.current.destroy();
                viewerRef.current = null;
            }
        };
    }, []);

    // Render Parcels on the Globe
    useEffect(() => {
        if (!viewerRef.current || !cesiumLoaded) return;

        const viewer = viewerRef.current;

        // Clear previous entities
        viewer.entities.removeAll();

        parcels.forEach(p => {
            if(p.boundary) {
                const rings = Array.isArray(p.boundary[0]) ? p.boundary : [p.boundary];

                // @ts-ignore
                rings.forEach((ring: any[]) => {
                    const positions: number[] = [];
                    ring.forEach(pt => {
                        positions.push(pt.lng);
                        positions.push(pt.lat);
                    });

                    viewer.entities.add({
                        name: p.name,
                        description: `
                            <div style="padding:10px;">
