export interface SoilData {
  texture: {
    sand: number; // %
    silt: number; // %
    clay: number; // %
    label: string; // USDA Class
  };
  chemistry: {
    ph: number;
    cec: number; // cmol(+)/kg
    nitrogen: number; // g/kg
  };
  organic: {
    soc: number; // %
    som: number; // % (Soil Organic Matter ~ SOC * 1.72)
  };
  physical: {
    bulkDensity: number; // g/cm³
  };
}

// USDA Soil Texture Triangle Logic
const getTextureClass = (sand: number, silt: number, clay: number): string => {
  if (clay >= 40) {
    if (sand > 45) return 'Sandy Clay';
    if (silt > 40) return 'Silty Clay';
    return 'Clay';
  }
  if (clay >= 27) {
    if (sand > 45) return 'Sandy Clay Loam';
    if (silt > 28) return 'Silty Clay Loam';
    return 'Clay Loam';
  }
  if (clay >= 12) {
    if (sand > 52) return 'Sandy Loam';
    if (silt > 50) return 'Silty Loam';
    return 'Loam';
  }
  // Clay < 12
  if (silt > 80) return 'Silt';
  if (sand > 85) return 'Sand';
  if (sand > 70) return 'Loamy Sand';
  return 'Sandy Loam'; // Fallback
};

// Weighted average for 0-30cm depth (Standard Topsoil)
// Depths used: 0-5cm (weight 5), 5-15cm (weight 10), 15-30cm (weight 15)
const calculateMean = (layers: any[], property: string, factor: number = 1): number => {
  const layer = layers.find((l: any) => l.name === property);
  if (!layer) return 0;

  try {
    const d0_5 = layer.depths.find((d: any) => d.label === '0-5cm')?.values?.mean || 0;
    const d5_15 = layer.depths.find((d: any) => d.label === '5-15cm')?.values?.mean || 0;
    const d15_30 = layer.depths.find((d: any) => d.label === '15-30cm')?.values?.mean || 0;

    const weightedSum = (d0_5 * 5) + (d5_15 * 10) + (d15_30 * 15);
    const totalWeight = 30;

    // Apply factor (scaling for units)
    return (weightedSum / totalWeight) / factor;
  } catch (e) {
    return 0;
  }
};

export const fetchSoilData = async (lat: number, lng: number): Promise<SoilData | null> => {
  try {
    // Correctly construct parameters for SoilGrids (repeated keys for arrays)
    const params = new URLSearchParams();
    params.append('lat', lat.toString());
    params.append('lon', lng.toString());

    const properties = ['clay', 'sand', 'silt', 'phh2o', 'soc', 'bdod', 'cec', 'nitrogen'];
    properties.forEach(p => params.append('property', p));

    const depths = ['0-5cm', '5-15cm', '15-30cm'];
    depths.forEach(d => params.append('depth', d));

    params.append('value', 'mean');

    // ISRIC SoilGrids REST API v2.0
    const url = `https://rest.soilgrids.org/soilgrids/v2.0/properties/query?${params.toString()}`;

    const response = await fetch(url);
    if (!response.ok) throw new Error('Soil API failed');

    const json = await response.json();
    const layers = json.properties?.layers;

    if (!layers) return null;

    // Unit Conversions based on SoilGrids documentation:
    // Clay/Sand/Silt: g/kg -> divide by 10 to get %
    // pH: pH*10 -> divide by 10
    // SOC: dg/kg -> divide by 100 to get % (10 g/kg = 1%)
    // Nitrogen: cg/kg -> divide by 100 to get g/kg
    // CEC: mmol(c)/kg -> divide by 10 to get cmol(+)/kg
    // Bulk Density: cg/cm³ -> divide by 100 to get g/cm³

    const clay = calculateMean(layers, 'clay', 10);
    const sand = calculateMean(layers, 'sand', 10);
    const silt = calculateMean(layers, 'silt', 10);
    const ph = calculateMean(layers, 'phh2o', 10);
    const soc = calculateMean(layers, 'soc', 100);
    const bdod = calculateMean(layers, 'bdod', 100);
    const cec = calculateMean(layers, 'cec', 10);
    const nitrogen = calculateMean(layers, 'nitrogen', 100);

    // Normalize texture to ensure 100% sum (minor API deviations)
    const total = clay + sand + silt;
    const normClay = total > 0 ? (clay / total) * 100 : 0;
    const normSand = total > 0 ? (sand / total) * 100 : 0;
    const normSilt = total > 0 ? (silt / total) * 100 : 0;

    return {
      texture: {
        clay: Number(normClay.toFixed(1)),
        sand: Number(normSand.toFixed(1)),
        silt: Number(normSilt.toFixed(1)),
        label: getTextureClass(normSand, normSilt, normClay)
      },
      chemistry: {
        ph: Number(ph.toFixed(1)),
        cec: Number(cec.toFixed(1)),
        nitrogen: Number(nitrogen.toFixed(2))
      },
      organic: {
        soc: Number(soc.toFixed(2)),
        som: Number((soc * 1.72).toFixed(2)) // Van Bemmelen factor
      },
      physical: {
        bulkDensity: Number(bdod.toFixed(2))
      }
    };

  } catch (error) {
    console.warn("Error fetching soil data:", error);
    return null;
  }
};

