interface FieldMonitorMapProps {
    parcel: Parcel;
    isOffline: boolean;
}

const FieldMonitorMap: React.FC<FieldMonitorMapProps> = ({ parcel, isOffline }) => {
    const mapRef = useRef<HTMLDivElement>(null);
    const mapInstanceRef = useRef<any>(null);
    const overlayRef = useRef<any>(null);
    const [activeLayer, setActiveLayer] = useState<'satellite' | 'ndvi' | 'lst' | 'soil'>('satellite');
    const [loadingLayer, setLoadingLayer] = useState(false);

    // Initialize Map
    useEffect(() => {
        if (!mapRef.current || !window.google) return;

        // Only initialize once
        if (mapInstanceRef.current) return;

        // Default center
        const center = { lat: 56.2639, lng: 9.5018 };

        const map = new window.google.maps.Map(mapRef.current, {
            center,
            zoom: 13,
            mapTypeId: 'hybrid',
            disableDefaultUI: true,
            zoomControl: true,
            streetViewControl: false,
        });
        mapInstanceRef.current = map;
    }, []);

    // Draw Parcel & Fit Bounds
    useEffect(() => {
        if (!mapInstanceRef.current || !parcel.boundary || !window.google) return;

        // Draw Polygon
        // Clear previous if any (though usually we just remount or rely on map cleanup if we stored references)
        // For simple usage, we assume this map is tied to this parcel.

        const polygon = new window.google.maps.Polygon({
            paths: parcel.boundary,
            strokeColor: '#f59e0b',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            fillColor: '#fbbf24',
            fillOpacity: 0.0,
        });
        polygon.setMap(mapInstanceRef.current);

        // Fit Bounds
        const bounds = new window.google.maps.LatLngBounds();

        if (Array.isArray(parcel.boundary)) {
            // Check if simple polygon or multipolygon
            const isMulti = Array.isArray(parcel.boundary[0]);
            if (isMulti) {
                (parcel.boundary as any[]).forEach(ring => {
                    ring.forEach((p: any) => bounds.extend(p));
                });
            } else {
                 (parcel.boundary as any[]).forEach((p: any) => bounds.extend(p));
            }
        }

        mapInstanceRef.current.fitBounds(bounds);

        // Return cleanup if needed, but for now we rely on component unmount to clear DOM
        return () => {
            polygon.setMap(null);
        };

    }, [parcel]);

    // Handle Layer Switching
    useEffect(() => {
        if (!mapInstanceRef.current || isOffline || !parcel.boundary) return;

        const loadLayer = async () => {
            setLoadingLayer(true);
            try {
                // Clear previous overlay
                if (overlayRef.current) {
                    mapInstanceRef.current.overlayMapTypes.removeAt(0);
                    overlayRef.current = null;
                }

                if (activeLayer === 'satellite') {
                    setLoadingLayer(false);
                    return;
                }

                const backendUrl = getBackendUrl();
                const tileUrl = await fetchGeeLayer(activeLayer, parcel.boundary, backendUrl);

                if (tileUrl) {
                    const mapType = new window.google.maps.ImageMapType({
                        getTileUrl: (coord: any, zoom: any) => {
                            return tileUrl
                                .replace('{x}', coord.x.toString())
                                .replace('{y}', coord.y.toString())
                                .replace('{z}', zoom.toString());
                        },
                        tileSize: new window.google.maps.Size(256, 256),
                        opacity: 0.7,
                        name: activeLayer
                    });

                    mapInstanceRef.current.overlayMapTypes.push(mapType);
                    overlayRef.current = mapType;
                }
            } catch (e) {
                console.error("Layer load failed", e);
            } finally {
                setLoadingLayer(false);
            }
        };

        loadLayer();
    }, [activeLayer, isOffline, parcel]);

    return (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
