export interface SoilData {
  texture: {
    sand: number | null; // %
    silt: number | null; // %
    clay: number | null; // %
    label: string; // USDA Class
  };
  chemistry: {
    ph: number | null;
    cec: number | null; // cmol(+)/kg
    nitrogen: number | null; // g/kg
  };
  organic: {
    soc: number | null; // %
    som: number | null; // % (Soil Organic Matter ~ SOC * 1.72)
  };
  physical: {
    bulkDensity: number | null; // g/cm³
  };
}

// USDA Soil Texture Triangle Logic
const getTextureClass = (sand: number | null, silt: number | null, clay: number | null): string => {
  if (sand === null || silt === null || clay === null) return 'N/A';

  if (clay >= 40) {
    if (sand > 45) return 'Sandy Clay';
    if (silt > 40) return 'Silty Clay';
    return 'Clay';
  }
  if (clay >= 27) {
    if (sand > 45) return 'Sandy Clay Loam';
    if (silt > 28) return 'Silty Clay Loam';
    return 'Clay Loam';
  }
  if (clay >= 12) {
    if (sand > 52) return 'Sandy Loam';
    if (silt > 50) return 'Silty Loam';
    return 'Loam';
  }
  // Clay < 12
  if (silt > 80) return 'Silt';
  if (sand > 85) return 'Sand';
  if (sand > 70) return 'Loamy Sand';
  return 'Sandy Loam'; // Fallback
};

// Weighted average for 0-30cm depth (Standard Topsoil)
// Depths used: 0-5cm (weight 5), 5-15cm (weight 10), 15-30cm (weight 15)
const calculateMean = (layers: any[], property: string, factor: number = 1): number | null => {
  const layer = layers.find((l: any) => l.name === property);
  if (!layer) return null;

  try {
    const d0_5 = layer.depths.find((d: any) => d.label === '0-5cm')?.values?.mean;
    const d5_15 = layer.depths.find((d: any) => d.label === '5-15cm')?.values?.mean;
    const d15_30 = layer.depths.find((d: any) => d.label === '15-30cm')?.values?.mean;

    // Strict check: if any depth is missing, return null to avoid skewing the average
    if (d0_5 === undefined || d5_15 === undefined || d15_30 === undefined) return null;

    const weightedSum = (d0_5 * 5) + (d5_15 * 10) + (d15_30 * 15);
    const totalWeight = 30;

    return (weightedSum / totalWeight) / factor;
  } catch (e) {
    return null;
  }
};

const safeFixed = (val: number | null, fractionDigits: number): number | null => {
    if (val === null) return null;
    return Number(val.toFixed(fractionDigits));
};

export const fetchSoilData = async (lat: number, lng: number): Promise<SoilData | null> => {
  try {
    const params = new URLSearchParams();
    params.append('lat', lat.toString());
    params.append('lon', lng.toString());

    const properties = ['clay', 'sand', 'silt', 'phh2o', 'soc', 'bdod', 'cec', 'nitrogen'];
    properties.forEach(p => params.append('property', p));

    const depths = ['0-5cm', '5-15cm', '15-30cm'];
    depths.forEach(d => params.append('depth', d));

    params.append('value', 'mean');

    // Add a timeout controller
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 8000); // 8 second timeout

    const url = `https://rest.soilgrids.org/soilgrids/v2.0/properties/query?${params.toString()}`;

    const response = await fetch(url, { signal: controller.signal });
    clearTimeout(timeoutId);

    if (!response.ok) throw new Error('Soil API failed');

    const json = await response.json();
    const layers = json.properties?.layers;

    if (!layers) throw new Error('No soil layers returned');

    const clay = calculateMean(layers, 'clay', 10);
    const sand = calculateMean(layers, 'sand', 10);
    const silt = calculateMean(layers, 'silt', 10);
    const ph = calculateMean(layers, 'phh2o', 10);
    const soc = calculateMean(layers, 'soc', 100);
    const bdod = calculateMean(layers, 'bdod', 100);
    const cec = calculateMean(layers, 'cec', 10);
    const nitrogen = calculateMean(layers, 'nitrogen', 100);

    // Normalize texture to ensure 100% sum (minor API deviations)
    let normClay: number | null = null;
    let normSand: number | null = null;
    let normSilt: number | null = null;

    if (clay !== null && sand !== null && silt !== null) {
        const total = clay + sand + silt;
        if (total > 0) {
            normClay = (clay / total) * 100;
            normSand = (sand / total) * 100;
            normSilt = (silt / total) * 100;
        }
    }

    return {
      texture: {
        clay: safeFixed(normClay, 1),
        sand: safeFixed(normSand, 1),
        silt: safeFixed(normSilt, 1),
        label: getTextureClass(normSand, normSilt, normClay)
      },
      chemistry: {
        ph: safeFixed(ph, 1),
        cec: safeFixed(cec, 1),
        nitrogen: safeFixed(nitrogen, 2)
      },
      organic: {
        soc: safeFixed(soc, 2),
        som: soc !== null ? safeFixed(soc * 1.72, 2) : null // Van Bemmelen factor
      },
      physical: {
        bulkDensity: safeFixed(bdod, 2)
      }
    };

  } catch (error) {
    console.warn("Soil API fetch failed:", error);
    return null;
  }
};

