export interface SoilData {
  texture: {
    sand: number | null; // %
    silt: number | null; // %
    clay: number | null; // %
    label: string; // USDA Class
  };
  chemistry: {
    ph: number | null;
    cec: number | null; // cmol(+)/kg
    nitrogen: number | null; // g/kg
  };
  organic: {
    soc: number | null; // %
    som: number | null; // % (Soil Organic Matter ~ SOC * 1.72)
  };
  physical: {
    bulkDensity: number | null; // g/cm³
  };
}

// USDA Soil Texture Triangle Logic
const getTextureClass = (sand: number | null, silt: number | null, clay: number | null): string => {
  if (sand === null || silt === null || clay === null) return 'N/A';

  if (clay >= 40) {
    if (sand > 45) return 'Sandy Clay';
    if (silt > 40) return 'Silty Clay';
    return 'Clay';
  }
  if (clay >= 27) {
    if (sand > 45) return 'Sandy Clay Loam';
    if (silt > 28) return 'Silty Clay Loam';
    return 'Clay Loam';
  }
  if (clay >= 12) {
    if (sand > 52) return 'Sandy Loam';
    if (silt > 50) return 'Silty Loam';
    return 'Loam';
  }
  // Clay < 12
  if (silt > 80) return 'Silt';
  if (sand > 85) return 'Sand';
  if (sand > 70) return 'Loamy Sand';
  return 'Sandy Loam'; // Fallback
};

const safeFixed = (val: number | null, fractionDigits: number): number | null => {
    if (val === null) return null;
    return Number(val.toFixed(fractionDigits));
};

// OpenLandMap API Base URL
const BASE_URL = 'https://api.openlandmap.org/query/point';

// Fetch helper for a specific layer code
const fetchLayer = async (lat: number, lon: number, code: string): Promise<number | null> => {
    try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), 8000); // 8 second timeout

        const response = await fetch(`${BASE_URL}?lat=${lat}&lon=${lon}&coll=layers&code=${code}`, {
            signal: controller.signal
        });
        clearTimeout(timeoutId);

        if (!response.ok) return null;

        const json = await response.json();

        // OpenLandMap returns depths as keys: b0, b10, b30, b60, b100, b200
        // We focus on topsoil (0-30cm avg)
        const v0 = typeof json.b0 === 'number' ? json.b0 : parseFloat(json.b0);
        const v10 = typeof json.b10 === 'number' ? json.b10 : parseFloat(json.b10);
        const v30 = typeof json.b30 === 'number' ? json.b30 : parseFloat(json.b30);

        let sum = 0;
        let count = 0;

        if (!isNaN(v0)) { sum += v0; count++; }
        if (!isNaN(v10)) { sum += v10; count++; }
        if (!isNaN(v30)) { sum += v30; count++; }

        if (count === 0) return null;

        return sum / count;
    } catch (e) {
        console.warn(`Failed to fetch OpenLandMap layer ${code}:`, e);
        return null;
    }
}

export const fetchSoilData = async (lat: number, lng: number): Promise<SoilData | null> => {
  try {
    // OpenLandMap Layer Codes
    // Clay: % (kg/kg)
    const CODE_CLAY = 'sol_clay.wfraction_usda.3a1a1a';
    // Sand: % (kg/kg)
    const CODE_SAND = 'sol_sand.wfraction_usda.3a1a1a';
    // pH: pH * 10
    const CODE_PH = 'sol_ph.h2o_usda.4a1a';
    // Organic Carbon: g/kg (10 g/kg = 1%)
    const CODE_SOC = 'sol_organic.carbon_usda.6a1c';
    // Bulk Density: 10 kg/m3 (100 = 1.0 g/cm3)
    const CODE_BD = 'sol_bulkden.fineearth_usda.4a1h';

    // Parallel Fetch
    const [clay, sand, ph, soc, bd] = await Promise.all([
        fetchLayer(lat, lng, CODE_CLAY),
        fetchLayer(lat, lng, CODE_SAND),
        fetchLayer(lat, lng, CODE_PH),
        fetchLayer(lat, lng, CODE_SOC),
        fetchLayer(lat, lng, CODE_BD)
    ]);

    // Normalize Units
    const normClay = clay !== null ? clay : null;
    const normSand = sand !== null ? sand : null;

    // Calculate Silt if possible
    let normSilt: number | null = null;
    if (normClay !== null && normSand !== null) {
        normSilt = 100 - (normClay + normSand);
        if (normSilt < 0) normSilt = 0;
    }

    const finalPh = ph !== null ? ph / 10 : null;
    const finalSoc = soc !== null ? soc / 10 : null; // Convert g/kg to %
    const finalBd = bd !== null ? bd / 100 : null; // Convert 10kg/m3 to g/cm3

    // We do not have reliable N/A layers for CEC/Nitrogen in this simplified OpenLandMap set, 
    // so they remain null (displaying N/A).

    return {
      texture: {
        clay: safeFixed(normClay, 1),
        sand: safeFixed(normSand, 1),
        silt: safeFixed(normSilt, 1),
        label: getTextureClass(normSand, normSilt, normClay)
      },
      chemistry: {
        ph: safeFixed(finalPh, 1),
        cec: null,
        nitrogen: null
      },
      organic: {
        soc: safeFixed(finalSoc, 2),
        som: finalSoc !== null ? safeFixed(finalSoc * 1.72, 2) : null
      },
      physical: {
        bulkDensity: safeFixed(finalBd, 2)
      }
    };

  } catch (error) {
    console.warn("OpenLandMap API fetch failed:", error);
    return null;
  }
};

