      keyObj = FALLBACK_KEY;
    }

    await eeInitializeWithPrivateKey(keyObj);
    console.log('✅ Earth Engine initialized');
    return true;
  } catch (err) {
    console.error('❌ Earth Engine initialization failed:', err.message || err);
    throw err;
  }
}

// Helper to wrap callback-style getMap into a Promise
function getMapIdAsync(image, visParams) {
  return new Promise((resolve, reject) => {
    try {
      // Visual refinement: 5m Downscale + Bilinear Resampling
      // We apply this just before visualization
      const visualImage = image
          .resample('bilinear')
          .reproject({ crs: image.projection(), scale: 5 });

      visualImage.getMap(visParams, (mapIdObj, errorMessage) => {
        if (errorMessage) {
            reject(new Error(errorMessage));
        } else {
            resolve(mapIdObj);
        }
      });
    } catch (err) {
      reject(err);
    }
  });
}

// Cache helper using Redis (string keys)
async function cacheGet(key) {
  try {
    const v = await redis.get(key);
    if (!v) return null;
    return JSON.parse(v);
  } catch (e) {
    return null;
  }
}
async function cacheSet(key, value, ttl = CACHE_TTL) {
  try {
    await redis.set(key, JSON.stringify(value), 'EX', ttl);
  } catch(e) {
    console.error("Redis Cache Set Error:", e.message);
  }
}

