app.post('/api/get-layer', async (req, res) => {
  try {
    const { polygon, layer = 'ndvi' } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    // Bump cache version to v4 to invalidate old non-resampled tiles
    const cacheKey = `map:v4:${layer}:${Buffer.from(JSON.stringify(polygon)).toString('base64')}`;
    const cached = await cacheGet(cacheKey);
    if (cached) {
        console.log(`Returning cached tile URL for ${layer}`);
        return res.json({ tile_url: cached });
    }

    const region = ee.Geometry(polygon);
    const end = ee.Date(Date.now());
    const start = end.advance(-90, 'day');

    let mapImage = null;
    let vis = null;

    // --- COLLECTION SELECTION ---
    // Sentinel-2
    const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
        .map((img) => img.updateMask(img.select('QA60').bitwiseAnd(1 << 10).eq(0)).divide(10000))
        .median()
        .clip(region);

    // Landsat 9 (Thermal)
    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(region)
        .filterDate(start, end)
        .sort('CLOUD_COVER')
        .first()
        .clip(region);

    switch (layer) {
        case 'ndvi':
            // Normalized Difference Vegetation Index
            // (NIR - Red) / (NIR + Red)
            mapImage = s2.normalizedDifference(['B8', 'B4']).rename('NDVI');
            vis = { min: 0, max: 0.8, palette: ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'] };
            break;

        case 'ndre':
            // Normalized Difference Red Edge
            // (NIR - RedEdge1) / (NIR + RedEdge1) -> (B8 - B5)
            // Useful for chlorophyll content and later growth stages
            mapImage = s2.normalizedDifference(['B8', 'B5']).rename('NDRE');
            vis = { min: 0.0, max: 0.6, palette: ['#a1662f', '#f59e0b', '#facc15', '#4ade80', '#15803d'] };
            break;

        case 'ndmi':
            // Normalized Difference Moisture Index
            // (NIR - SWIR1) / (NIR + SWIR1) -> (B8 - B11)
            mapImage = s2.normalizedDifference(['B8', 'B11']).rename('NDMI');
            vis = { min: -0.2, max: 0.4, palette: ['#caf0f8', '#90e0ef', '#00b4d8', '#0077b6', '#03045e'] };
            break;

        case 'lai':
            // Leaf Area Index (Approximation)
            // Empirical formula: LAI = 0.57 * exp(2.33 * NDVI)
            const ndvi = s2.normalizedDifference(['B8', 'B4']);
            mapImage = ndvi.multiply(2.33).exp().multiply(0.57).rename('LAI');
            vis = { min: 0, max: 5, palette: ['#f7fcf5', '#caeac3', '#7bc77c', '#2a924a', '#00441b'] };
            break;

        case 'lst':
            // Land Surface Temperature (Landsat)
            const kelvin = l9.select('ST_B10').multiply(0.00341802).add(149.0);
            mapImage = kelvin.subtract(273.15).rename('LST');
            vis = { min: 15, max: 35, palette: ['blue', 'yellow', 'red'] };
            break;

        default:
            // Fallback to NDVI if unknown
            mapImage = s2.normalizedDifference(['B8', 'B4']);
            vis = { min: 0, max: 0.8, palette: ['#a1662f', '#eab308', '#84cc16', '#22c55e', '#14532d'] };
    }

    console.log(`Generating map for ${layer} (5m downscaled)...`);
    const mapid = await getMapIdAsync(mapImage, vis);

    let tileUrl = null;
    if (mapid) {
        if (mapid.urlFormat) {
            tileUrl = mapid.urlFormat;
        } else if (mapid.tile_fetcher && mapid.tile_fetcher.url_format) {
            tileUrl = mapid.tile_fetcher.url_format;
        } else if (mapid.mapid && mapid.token) {
            tileUrl = `https://earthengine.googleapis.com/map/${mapid.mapid}/{z}/{x}/{y}?token=${mapid.token}`;
        }
    }

    if (!tileUrl) throw new Error('Could not generate tile URL from Earth Engine response');

    await cacheSet(cacheKey, tileUrl, 60);
    return res.json({ tile_url: tileUrl });
  } catch (err) {
    console.error('Error in /api/get-layer:', err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

app.post('/api/get-stats', async (req, res) => {
  try {
    const { polygon, months = 6, startDate, endDate } = req.body;
    if (!polygon) return res.status(400).json({ error: 'polygon required' });
    validatePolygon(polygon);

    console.log('Enqueuing stats job...');
    // IMPORTANT: removeOnComplete must be FALSE (or a large number) so the result 
    // persists in Redis long enough for the polling GET request to retrieve it.
    const job = await ndviQueue.add(
        { polygon, months, startDate, endDate }, 
        { removeOnComplete: false, removeOnFail: false }
    );
    return res.json({ jobId: job.id });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

app.get('/api/job/:id', async (req, res) => {
  try {
    const job = await ndviQueue.getJob(req.params.id);
    if (!job) {
        // Log locally so we know why the frontend is getting 404s
        console.log(`Job ID ${req.params.id} not found in Redis.`);
        return res.status(404).json({ error: 'job not found' });
    }
    const state = await job.getState();
    const result = await job.returnvalue;

    // Log state to help debugging "infinite processing"
    if (state === 'completed') {
        console.log(`Job ${job.id} is COMPLETED. Returning result size: ${JSON.stringify(result).length} chars`);
    }

    return res.json({ id: job.id, state, result });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: err.message || String(err) });
  }
});

