// Helper to wrap callback-style getMap into a Promise
function getMapIdAsync(image, visParams) {
  return new Promise((resolve, reject) => {
    try {
      // PERFORMANCE OPTIMIZATION & VISUAL ENHANCEMENT
      // 1. Removed .reproject() which was causing slow rendering times.
      // 2. Added Unsharp Mask for "sharpening" edges.
      // 3. Used 'bicubic' resampling for "strong smoothing" of pixel blocks.

      // Unsharp Mask: sharpened = original + (original - blurred) * amount
      const sigma = 1; // Radius for Gaussian blur (smoothing before edge detection)
      const amount = 1; // Strength of the sharpening effect

      const blurred = image.convolve(ee.Kernel.gaussian(sigma));
      const unsharp = image.subtract(blurred);
      const sharpened = image.add(unsharp.multiply(amount));

      // Bicubic Resampling: Smoothes out the grid/pixels much better than bilinear
      const visualImage = sharpened.resample('bicubic');

      visualImage.getMap(visParams, (mapIdObj, errorMessage) => {
        if (errorMessage) {
            reject(new Error(errorMessage));
        } else {
            resolve(mapIdObj);
        }
      });
    } catch (err) {
      reject(err);
    }
  });
}

