// Simple helper to promisify ee calls that use callbacks
function eeInitializeWithPrivateKey(keyObj) {
  return new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(keyObj, () => {
      // After authenticating, initialize
      ee.initialize(null, null, () => {
        resolve();
      }, (err) => reject(new Error('ee.initialize error: ' + err)));
    }, (err) => reject(new Error('authenticateViaPrivateKey error: ' + err)));
  });
}

async function initializeEarthEngine() {
  try {
    let keyObj = null;
    if (process.env.EE_PRIVATE_KEY && process.env.EE_CLIENT_EMAIL) {
      keyObj = {
        private_key: process.env.EE_PRIVATE_KEY.replace(/\\n/g, '\n'),
        client_email: process.env.EE_CLIENT_EMAIL,
      };
    } else if (fs.existsSync(EE_KEY_FILE)) {
      keyObj = require(path.resolve(EE_KEY_FILE));
    } else {
      console.log("⚠️ No key file found, using embedded fallback credentials.");
      keyObj = FALLBACK_KEY;
    }

    await eeInitializeWithPrivateKey(keyObj);
    console.log('✅ Earth Engine initialized');
    return true;
  } catch (err) {
    console.error('❌ Earth Engine initialization failed:', err.message || err);
    throw err;
  }
}

// Helper: Calculate Dynamic Min/Max based on 2nd and 98th Percentiles
// This "Automatic Scale" ensures maximum visual variation.
function getDynamicVisualizedImage(image, region, bandName, palette) {
    // 1. Calculate statistics (Min/Max based on percentiles to ignore outliers)
    const stats = image.reduceRegion({
        reducer: ee.Reducer.percentile([2, 98]),
        geometry: region,
        scale: 20, // Lower scale for speed (20m is sufficient for stats)
        maxPixels: 1e9,
        bestEffort: true
    });

    // 2. Extract values (client-side of Earth Engine logic)
    const minVal = stats.getNumber(bandName + '_p2');
    const maxVal = stats.getNumber(bandName + '_p98');

    // 3. Apply stretch using visualize(). 
    // This returns an RGB image (3 bands: vis-red, vis-green, vis-blue)
    return image.visualize({
        min: minVal,
        max: maxVal,
        palette: palette,
        forceRgbOutput: true
    });
}

// Helper to wrap callback-style getMap into a Promise
function getMapIdAsync(image) {
  return new Promise((resolve, reject) => {
    try {
      // Simplified Resampling: Bilinear
      const visualImage = image.resample('bilinear');

      // Note: No visParams passed here because image is already RGB visualized
      visualImage.getMap({}, (mapIdObj, errorMessage) => {
        if (errorMessage) {
            reject(new Error(errorMessage));
        } else {
            resolve(mapIdObj);
        }
      });
    } catch (err) {
      reject(err);
    }
  });
}

// Cache helper using Redis (string keys)
async function cacheGet(key) {
  try {
    const v = await redis.get(key);
    if (!v) return null;
    return JSON.parse(v);
  } catch (e) {
    return null;
  }
}
async function cacheSet(key, value, ttl = CACHE_TTL) {
  try {
    await redis.set(key, JSON.stringify(value), 'EX', ttl);
  } catch(e) {
    console.error("Redis Cache Set Error:", e.message);
  }
}

