        // Let's add cleanup just in case.

        const polygon = new window.google.maps.Polygon({
            paths: parcel.boundary,
            strokeColor: '#f59e0b',
            strokeOpacity: 0.8,
            strokeWeight: 2,
            fillColor: '#fbbf24',
            fillOpacity: 0.0,
