export const FieldDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { parcels, loading: contextLoading } = useParcels();

  const [parcel, setParcel] = useState<Parcel | null>(null);
  const [weather, setWeather] = useState<WeatherData | null>(null);
  const [soil, setSoil] = useState<SoilData | null>(null);
  const [ndviHistory, setNdviHistory] = useState<{date: string, value: number}[]>([]);

  const [loading, setLoading] = useState(true);
  const [statsLoading, setStatsLoading] = useState(false);
  const [isOffline, setIsOffline] = useState(false);

  useEffect(() => {
    setIsOffline(localStorage.getItem('gee_simulation_mode') === 'true');
  }, []);

  useEffect(() => {
    // If context is still loading, wait
    if (contextLoading) return;

    if (id) {
      const p = parcels.find(item => item.id === id);
      if (p) {
        setParcel(p);
      } else {
        setLoading(false); // Finished loading, but found nothing
      }
    }
  }, [id, parcels, contextLoading]);

  useEffect(() => {
    if (!parcel) return;

    const loadData = async () => {
      setLoading(true);
      try {
        const { lat, lng } = getCoordinates(parcel.location);

        // Weather & Soil
        const [wData, sData] = await Promise.all([
          fetchFieldWeather(lat, lng),
          fetchSoilData(lat, lng)
        ]);

        setWeather(wData);
        setSoil(sData);

        // Stats (Independent)
        loadStats();

      } catch (e) {
        console.error("Error loading external API data", e);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [parcel]);

  const loadStats = async () => {
    if (!parcel || !parcel.boundary) return;

    setStatsLoading(true);
    try {
        const backendUrl = getBackendUrl();
        const endDate = new Date().toISOString().split('T')[0];
        const startDate = new Date();
        startDate.setMonth(startDate.getMonth() - 6);
        const startDateStr = startDate.toISOString().split('T')[0];

        const stats = await fetchGeeTimeSeries(parcel.boundary, startDateStr, endDate, backendUrl);
        if (stats) {
            setNdviHistory(stats);
        }
    } catch (e) {
        console.error("Stats load failed", e);
    } finally {
        setStatsLoading(false);
    }
  };

  if (contextLoading || (loading && !parcel)) {
      return (
          <div className="h-full w-full flex items-center justify-center">
             <Loader2 size={40} className="animate-spin text-emerald-800" />
          </div>
      );
  }

  if (!parcel) {
      return (
          <div className="p-8 text-center">
              <h2 className="text-xl font-bold text-gray-800">Field Not Found</h2>
              <button onClick={() => navigate('/dashboard')} className="mt-4 text-emerald-600 hover:underline">Return to Dashboard</button>
          </div>
      );
  }

  return (
    <div className="space-y-6 pb-12">
      {/* Header */}
      <div className="flex items-center justify-between">
         <div className="flex items-center gap-4">
             <button 
                onClick={() => navigate('/dashboard')}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500"
             >
                 <ArrowLeft size={24} />
             </button>
             <div>
                 <h1 className="text-2xl font-bold text-gray-900">{parcel.name}</h1>
                 <p className="text-gray-500 text-sm flex items-center gap-2">
                     <MapPin size={14} /> {parcel.location} • {parcel.crop} • {parcel.size} ha
                 </p>
             </div>
         </div>
         <div className="flex gap-2">
            <button className="px-4 py-2 bg-emerald-800 text-white rounded-lg text-sm font-medium hover:bg-emerald-900 transition-colors flex items-center gap-2">
                <SettingsIcon size={16} /> Field Settings
            </button>
         </div>
      </div>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

          {/* Left Column (2/3): Map & Chart */}
          <div className="lg:col-span-2 space-y-6">

              {/* Satellite Map */}
              <div className="h-[450px]">
                 <FieldMonitorMap parcel={parcel} isOffline={isOffline} />
              </div>

              {/* NDVI Chart */}
              <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-6">
                  <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-3">
                          <div className="p-2 bg-emerald-100 rounded-lg text-emerald-800">
                              <Activity size={20} />
                          </div>
                          <div>
                              <h3 className="font-bold text-gray-900">Crop Health Trends (NDVI)</h3>
                              <p className="text-xs text-gray-500">6 Month Historical Data</p>
                          </div>
                      </div>
                      {statsLoading && <Loader2 className="animate-spin text-emerald-600" size={16} />}
                  </div>

                  <div className="h-[300px] w-full">
                      {ndviHistory.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={ndviHistory}>
                                <defs>
